import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/dcci.C5dXLgE4.png",A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"缓存控制","link":"/api/SIMD-API/basic_api/cache_control/cache_control"},{"text":"DataCacheCleanAndInvalid","link":"/api/SIMD-API/basic_api/cache_control/DataCacheCleanAndInvalid"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cache_control/DataCacheCleanAndInvalid.md","filePath":"api/SIMD-API/basic_api/cache_control/DataCacheCleanAndInvalid.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788180402000}'),t={name:"api/SIMD-API/basic_api/cache_control/DataCacheCleanAndInvalid.md"};function e(i,s,d,o,h,r){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>DataCacheCleanAndInvalid<span id="ZH-CN_TOPIC_0000001787873306"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_cache_intf.h&quot;</code>。</p><p>如图1所示，在AI Core内部，Scalar单元和DMA单元都可能对GM进行访问：</p><ul><li>DMA搬运单元读写GM，数据通过DataCopy等接口在Unified Buffer（UB）等Local Memory和GM间交互，没有Cache一致性问题。</li><li>Scalar单元访问GM，首先会访问每个核内的Data Cache，因此存在Data Cache与GM的Cache一致性问题。</li></ul><p><strong>图1</strong> DataCache内存层次示意图<span id="zh-cn_topic_0000002530021782_fig1161014168448"></span></p><p><img src="'+c+`" alt></p><p>DataCacheCleanAndInvalid接口用于解决上述一致性问题，其功能可以拆解为两部分：</p><ul><li>Clean：将缓存中被修改过的数据（脏数据，Dirty Data）写回到GM中，避免数据丢失。</li><li>Invalid： <ul><li>将指定地址范围的Cache Line标记为“无效”，使其从缓存中移除。</li><li>保证下一次访问这些内存地址时，会从GM重新加载数据，而不是使用可能过期的缓存数据。</li></ul></li></ul><p>该接口的典型使用场景如下：</p><ul><li>读取GM的数据，但该数据可能在外部被其余核修改，此时需要使用DataCacheCleanAndInvalid接口，直接访问GM，获取最新数据。</li><li>用户通过Scalar单元写GM的数据，希望立刻写出，也需要使用DataCacheCleanAndInvalid接口。</li></ul><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，原子操作过程中，如果希望改变后续数据的饱和模式，需要先使用DataCacheCleanAndInvalid接口将Cache Line中现存的数据立刻写出，再调用<a href="../special_register_access/SetCtrlSpr_ISASI.html">SetCtrlSpr</a>设置后续数据的饱和模式。</li></ul></div><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>配置dcciDst的原型</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 支持通过配置dcciDst确保DCache与GM存储的一致性。</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="n">CacheLine</span><span class="w"> </span><span class="n">entireType</span><span class="p">,</span><span class="w"> </span><span class="n">DcciDst</span><span class="w"> </span><span class="n">dcciDst</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCacheCleanAndInvalid</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">)</span>
<span class="c1">// 支持通过配置dcciDst确保DCache与Local Memory存储的一致性。</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="n">CacheLine</span><span class="w"> </span><span class="n">entireType</span><span class="p">,</span><span class="w"> </span><span class="n">DcciDst</span><span class="w"> </span><span class="n">dcciDst</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCacheCleanAndInvalid</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">)</span>
</code></pre></div></li><li><p>不支持配置dcciDst，仅支持保证DCache与GM的一致性。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="n">CacheLine</span><span class="w"> </span><span class="n">entireType</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCacheCleanAndInvalid</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">)</span>
</code></pre></div></li></ul><div data-filter="310p"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>对于Atlas 推理系列产品AI Core，仅支持不配置dcciDst参数的原型。</p></div></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>dst的数据类型。</td></tr><tr><td>entireType</td><td>指令操作的模式：<br>SINGLE_CACHE_LINE：只刷新传入地址所在的Cache Line，<strong>注意如果该地址非64B对齐，只会操作传入地址到64B对齐的部分。</strong><br>ENTIRE_DATA_CACHE：此时传入的地址无效，核内会刷新整个DCache，但是耗时较大，<strong>性能敏感的场景慎用</strong>。</td></tr><tr><td>dcciDst</td><td>表示使用该接口来保证DCache与哪一种存储保持一致性，类型为DcciDst枚举类。<br>• CACHELINE_ALL：与CACHELINE_OUT效果一致。<br>• CACHELINE_UB：表示通过该接口来保证DCache与UB的一致性。<br>• CACHELINE_OUT：表示通过该接口来保证DCache与GM的一致性。<br>• CACHELINE_ATOMIC：原子操作过程中保证DCache和GM的一致性。<br><span data-filter="950">  - Ascend 950PR/Ascend 950DT，支持。<br></span><span data-filter="A3">  - Atlas A3 训练系列产品/Atlas A3 推理系列产品，暂未支持。<br></span><span data-filter="910b">  - Atlas A2 训练系列产品/Atlas A2 推理系列产品，暂未支持。<br></span><span data-filter="310b">  - Atlas 200I/500 A2 推理产品，暂未支持。<br></span><span data-filter="310p">  - Atlas 推理系列产品AI Core，暂未支持。</span></td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输入</td><td>需要刷新Cache的Tensor。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>当<code>entireType</code>为<code>SINGLE_CACHE_LINE</code>时，<code>dst</code>生效，<code>dcciDst</code>不生效。</li><li>当<code>entireType</code>为<code>ENTIRE_DATA_CACHE</code>时，<code>dst</code>不生效，<code>dcciDst</code>生效。</li><li><code>dst</code>为<code>LocalTensor</code>类型的函数原型仅支持在AIV中调用。</li></ul><h2 id="调用示例">调用示例<span id="section837496171220"></span><a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p><strong>示例1：SINGLE_CACHE_LINE模式（64B对齐场景）</strong><br> 假设mmAddr_为0x40（64B对齐），调用一次指令即可刷新整个Cache Line。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">global</span><span class="p">;</span>
<span class="n">global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">*</span><span class="p">)</span><span class="n">mmAddr_</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="p">);</span>
<span class="k">for</span><span class="p">(</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">global</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">());</span>
<span class="p">}</span>
<span class="c1">// 由于首地址64B对齐，调用DataCacheCleanAndInvalid指令后，会立刻刷新前8个数。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCacheCleanAndInvalid</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheLine</span><span class="o">::</span><span class="n">SINGLE_CACHE_LINE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DcciDst</span><span class="o">::</span><span class="n">CACHELINE_OUT</span><span class="o">&gt;</span><span class="p">(</span><span class="n">global</span><span class="p">);</span>
</code></pre></div></li><li><p><strong>示例2：SINGLE_CACHE_LINE模式（非64B对齐场景）</strong><br> 假设mmAddr_为0x20（非64B对齐），需要调用两次指令才能刷新完整Cache Line。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">global</span><span class="p">;</span>
<span class="n">global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">*</span><span class="p">)</span><span class="n">mmAddr_</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="p">);</span>
<span class="k">for</span><span class="p">(</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">global</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">());</span>
<span class="p">}</span>
<span class="c1">// 由于首地址非64B对齐，调用1条指令，只会刷新起始地址至64B字节对齐的部分，即前4个数。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCacheCleanAndInvalid</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheLine</span><span class="o">::</span><span class="n">SINGLE_CACHE_LINE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DcciDst</span><span class="o">::</span><span class="n">CACHELINE_OUT</span><span class="o">&gt;</span><span class="p">(</span><span class="n">global</span><span class="p">);</span>
<span class="c1">// 需要再次调用DataCacheCleanAndInvalid指令，刷新后4个数。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCacheCleanAndInvalid</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheLine</span><span class="o">::</span><span class="n">SINGLE_CACHE_LINE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DcciDst</span><span class="o">::</span><span class="n">CACHELINE_OUT</span><span class="o">&gt;</span><span class="p">(</span><span class="n">global</span><span class="p">[</span><span class="mi">4</span><span class="p">]);</span>
</code></pre></div></li><li><p><strong><span id="example3_multi_core"></span>示例3：SINGLE_CACHE_LINE模式（多核处理场景）</strong><br> 假设mmAddr_为0x40（64B对齐），多核操作同一条Cache Line时可能出现随机覆盖。本样例仅做示例说明，便于开发者理解使用限制，非正常使用样例。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">global</span><span class="p">;</span>
<span class="n">global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">*</span><span class="p">)</span><span class="n">mmAddr_</span><span class="p">);</span>
<span class="n">global</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">(),</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">());</span>
<span class="c1">// 算子中多核操作虽然不在同一个地址，但在同一个Cache Line，会出现数据的随机覆盖，和通用CPU的行为不同。</span>
<span class="c1">// 调用DataCacheCleanAndInvalid指令后，由于多核操作的时间不一致，最终结果存在随机性，后执行的核会覆盖前面核的结果。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCacheCleanAndInvalid</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheLine</span><span class="o">::</span><span class="n">SINGLE_CACHE_LINE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DcciDst</span><span class="o">::</span><span class="n">CACHELINE_OUT</span><span class="o">&gt;</span><span class="p">(</span><span class="n">global</span><span class="p">);</span>
</code></pre></div></li><li><p><strong>示例4：ENTIRE_DATA_CACHE模式</strong><br> 假设mmAddr_为0x20（非64B对齐），刷新整个DCache。本样例仅做示例说明，便于开发者理解使用限制，非正常使用样例。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">global</span><span class="p">;</span>
<span class="n">global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">*</span><span class="p">)</span><span class="n">mmAddr_</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="p">);</span>
<span class="k">for</span><span class="p">(</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">global</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">());</span>
<span class="p">}</span>
<span class="c1">// 刷新整个DCache，性能较差。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCacheCleanAndInvalid</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheLine</span><span class="o">::</span><span class="n">ENTIRE_DATA_CACHE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DcciDst</span><span class="o">::</span><span class="n">CACHELINE_OUT</span><span class="o">&gt;</span><span class="p">(</span><span class="n">global</span><span class="p">);</span>
</code></pre></div></li></ul></article></div>`,1)])])}const v=a(t,[["render",e]]);export{A as __pageData,v as default};
